parameters.jsCode:
const norm = (v) => String(v ?? '')
  .normalize('NFKD')
  .replace(/[\u0300-\u036f]/g, '')
  .toLowerCase()
  .replace(/&/g, ' and ')
  .replace(/[^a-z0-9]+/g, ' ')
  .replace(/\s+/g, ' ')
  .trim();

const normCompany = (v) => norm(v)
  .replace(/\b(pte ltd|private limited|pte|ltd|limited|singapore|sg)\b/g, ' ')
  .replace(/\s+/g, ' ')
  .trim();


// --------------------------------------------------
// PARSE JSON AI
// --------------------------------------------------

const parse = (raw) => {

  if (typeof raw !== 'string') {
    return null;
  }

  let s = raw
    .trim()
    .replace(/^```(?:json)?\s*/i, '')
    .replace(/```\s*$/i, '')
    .trim();

  const a = s.indexOf('{');
  const b = s.lastIndexOf('}');

  if (a >= 0 && b > a) {
    s = s.slice(a, b + 1);
  }

  try {
    return JSON.parse(s);
  } catch {
    return null;
  }
};


// --------------------------------------------------
// ESTRAZIONE DOMINIO
// --------------------------------------------------

const getDomain = (sito) => {

  let dominio = String(sito ?? '')
    .trim()
    .toLowerCase()
    .replace(/^https?:\/\//i, '')
    .replace(/^www\./i, '')
    .split('/')[0]
    .split('?')[0]
    .split('#')[0]
    .trim();

  return dominio;
};


// --------------------------------------------------
// PULIZIA PARTI DEL NOME
// --------------------------------------------------

const cleanNamePart = (v) => String(v ?? '')
  .normalize('NFKD')
  .replace(/[\u0300-\u036f]/g, '')
  .toLowerCase()
  .replace(/[^a-z0-9]/g, '');


// --------------------------------------------------
// TITOLI DA IGNORARE
// --------------------------------------------------

const prefissiDaIgnorare = new Set([
  'dr',
  'doctor',
  'mr',
  'mrs',
  'ms',
  'miss',
  'prof',
  'professor',
  'sir',
  'madam',
  'md'
]);


// --------------------------------------------------
// GENERAZIONE EMAIL PROBABILI
// --------------------------------------------------

const generaEmail = (
  nomeCompleto,
  dominio
) => {

  if (
    !nomeCompleto ||
    !dominio
  ) {
    return [];
  }

  let parti = String(nomeCompleto)
    .trim()
    .split(/\s+/)
    .map(cleanNamePart)
    .filter(Boolean);


  // Rimuove eventuali titoli iniziali
  while (
    parti.length > 1 &&
    prefissiDaIgnorare.has(
      parti[0]
    )
  ) {
    parti.shift();
  }


  if (parti.length === 0) {
    return [];
  }


  const first =
    parti[0];


  // Caso con un solo nome
  if (parti.length === 1) {

    return [
      `${first}@${dominio}`
    ];

  }


  const last =
    parti[
      parti.length - 1
    ];


  return [

    `${first}.${last}@${dominio}`,

    `${first}@${dominio}`,

    `${first.charAt(0)}${last}@${dominio}`

  ];
};


// --------------------------------------------------
// ARCHIVIO PROSPECT GIÀ PRESENTI
// --------------------------------------------------

const archivio =
  $('Prepara archivio')
    .first()
    .json;


const visti =
  new Set(
    archivio
      .chiavi_esistenti ||
    []
  );


const nomiVisti =
  new Set(
    archivio
      .nomi_esistenti ||
    []
  );


const nuovi = [];


// --------------------------------------------------
// ELABORAZIONE RISULTATI AI
// --------------------------------------------------

for (
  const item of $input.all()
) {

  const dati =
    parse(
      item.json.output
    );


  if (
    !dati ||
    !Array.isArray(
      dati.candidati
    )
  ) {
    continue;
  }


  for (
    const c of dati.candidati
  ) {


    // --------------------------------------------------
    // NOME COMPLETO
    // --------------------------------------------------

    const nome =
      String(
        c?.nome ?? ''
      )
        .trim()
        .replace(
          /\s+/g,
          ' '
        );


    // --------------------------------------------------
    // NOME PROPRIO PER MAILUP
    // --------------------------------------------------

    const nomeMailup =
      String(
        c?.nome_proprio ?? ''
      )
        .trim()
        .replace(
          /\s+/g,
          ' '
        );


    // --------------------------------------------------
    // COGNOME PER MAILUP
    // --------------------------------------------------

    const cognomeMailup =
      String(
        c?.cognome ?? ''
      )
        .trim()
        .replace(
          /\s+/g,
          ' '
        );


    // --------------------------------------------------
    // AZIENDA
    // --------------------------------------------------

    const azienda =
      String(
        c?.azienda ?? ''
      )
        .trim()
        .replace(
          /\s+/g,
          ' '
        );


    const nomeN =
      norm(nome);

    const aziendaN =
      normCompany(
        azienda
      );


    if (
      !nomeN ||
      !aziendaN
    ) {
      continue;
    }


    // --------------------------------------------------
    // CHIAVE DUPLICATO
    // --------------------------------------------------

    const key =
      `${nomeN}|${aziendaN}`;


    // Nome + azienda già presenti
    if (
      visti.has(key)
    ) {
      continue;
    }


    // Persona già presente
    if (
      nomiVisti.has(
        nomeN
      )
    ) {
      continue;
    }


    // --------------------------------------------------
    // FONTE
    // --------------------------------------------------

    const fonte =
      typeof c?.fonte ===
        'string' &&
      /^https?:\/\//i.test(
        c.fonte.trim()
      )
        ? c.fonte.trim()
        : '';


    if (!fonte) {
      continue;
    }


    // --------------------------------------------------
    // SITO
    // --------------------------------------------------

    const sito =
      c?.sito
        ? String(
            c.sito
          ).trim()
        : '';


    // Scarta prospect senza sito
    if (!sito) {
      continue;
    }


    const dominio =
      getDomain(
        sito
      );


    // Scarta siti da cui non
    // ricaviamo un dominio valido
    if (!dominio) {
      continue;
    }


    // --------------------------------------------------
    // EMAIL PROBABILI
    // --------------------------------------------------

    const emailProbabili =
      generaEmail(
        nome,
        dominio
      );


    // --------------------------------------------------
    // SEGNA COME VISTO
    // --------------------------------------------------

    visti.add(
      key
    );

    nomiVisti.add(
      nomeN
    );


    // --------------------------------------------------
    // OUTPUT
    // --------------------------------------------------

    nuovi.push({

      json: {

        // Nome completo usato
        // dal workflow attuale
        'Nome':
          nome,


        // Campi aggiuntivi
        // per il foglio Mailup
        'Nome Mailup':
          nomeMailup,

        'Cognome Mailup':
          cognomeMailup,


        'Azienda':
          azienda,


        'Ruolo proposto':
          String(
            c?.ruolo ?? ''
          ).trim(),


        'Settore':
          String(
            c?.settore ?? ''
          ).trim(),


        'Sito':
          sito,


        'Email probabile/i':
          emailProbabili
            .join(', '),


        'Fonte analizzata':
          fonte

      }

    });

  }

}


// --------------------------------------------------
// RISULTATO
// --------------------------------------------------

return nuovi;

const prospect = $('Deduplica e prepara righe').item.json;

let html = String($json.html ?? '');

// --------------------------------------------------
// FUNZIONI URL SENZA new URL()
// --------------------------------------------------

const cleanHost = (raw) => {
  let s = String(raw ?? '')
    .trim()
    .toLowerCase();

  if (!s) return '';

  s = s
    .replace(/^https?:\/\//i, '')
    .replace(/^\/\//, '');

  s = s
    .split('/')[0]
    .split('?')[0]
    .split('#')[0]
    .replace(/^www\./, '')
    .replace(/:\d+$/, '');

  return s;
};


const normalizeUrl = (raw) => {
  let s = String(raw ?? '').trim();

  if (!s) return '';

  s = s
    .replace(/^https?:\/\//i, '')
    .replace(/^\/\//, '');

  const parti = s.split('/');

  const host = String(parti.shift() ?? '')
    .toLowerCase()
    .replace(/^www\./, '')
    .replace(/:\d+$/, '');

  let path = '/' + parti.join('/');

  path = path
    .split('?')[0]
    .split('#')[0]
    .replace(/\/+$/, '');

  if (!path) {
    path = '/';
  }

  return host + path.toLowerCase();
};


const decodeCfEmail = (encoded) => {
  try {

    if (!encoded || encoded.length < 4) {
      return '';
    }

    const key =
      parseInt(encoded.slice(0, 2), 16);

    let email = '';

    for (
      let i = 2;
      i < encoded.length;
      i += 2
    ) {
      email += String.fromCharCode(
        parseInt(
          encoded.slice(i, i + 2),
          16
        ) ^ key
      );
    }

    return email;

  } catch {
    return '';
  }
};


// --------------------------------------------------
// DECODIFICA HTML
// --------------------------------------------------

html = html
  .replace(/&#(\d+);/g, (_, n) =>
    String.fromCharCode(Number(n))
  )
  .replace(/&#x([0-9a-f]+);/gi, (_, n) =>
    String.fromCharCode(
      parseInt(n, 16)
    )
  )
  .replace(/&commat;/gi, '@')
  .replace(/\\u0040/gi, '@')
  .replace(/\\u002e/gi, '.')
  .replace(/\\x40/gi, '@')
  .replace(/\\x2e/gi, '.')
  .replace(/%40/gi, '@')
  .replace(/%2e/gi, '.');


// --------------------------------------------------
// ESTRAZIONE EMAIL DALLA HOMEPAGE
// --------------------------------------------------

const trovate = [];


// Cloudflare
const cfRegex =
  /data-cfemail=["']([0-9a-f]+)["']/gi;

let cfMatch;

while (
  (cfMatch = cfRegex.exec(html)) !== null
) {

  const decoded =
    decodeCfEmail(cfMatch[1]);

  if (decoded) {
    trovate.push(decoded);
  }
}


// mailto:
const mailtoRegex =
  /mailto:([^"'?#\s<>]+)/gi;

let mailMatch;

while (
  (mailMatch = mailtoRegex.exec(html)) !== null
) {

  let value = mailMatch[1];

  try {
    value = decodeURIComponent(value);
  } catch {}

  trovate.push(value);
}


// Email normali
const plainEmails =
  html.match(
    /[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/gi
  ) || [];

trovate.push(...plainEmails);


// --------------------------------------------------
// NORMALIZZAZIONE EMAIL
// --------------------------------------------------

const tutteEmail = [
  ...new Set(
    trovate
      .map(email =>
        String(email)
          .toLowerCase()
          .trim()
          .replace(
            /[),.;:'"]+$/g,
            ''
          )
      )
      .filter(email =>
        /^[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}$/i
          .test(email)
      )
  )
];


// --------------------------------------------------
// FILTRO DOMINIO AZIENDALE
// --------------------------------------------------

const dominio =
  cleanHost(prospect.Sito);

const emailDominio =
  tutteEmail.filter(email => {

    const dominioEmailRaw =
      String(
        email.split('@')[1] ?? ''
      )
        .toLowerCase()
        .trim();

    if (
      !dominioEmailRaw ||
      !dominio
    ) {
      return false;
    }

    // Scarta robe tipo nome@www.azienda.com
    if (
      dominioEmailRaw.startsWith('www.')
    ) {
      return false;
    }

    const dominioEmail =
      dominioEmailRaw
        .replace(/^www\./, '');

    return (
      dominioEmail === dominio ||
      dominioEmail.endsWith(
        '.' + dominio
      )
    );
  });


// --------------------------------------------------
// EMAIL GENERICHE / PERSONALI
// --------------------------------------------------

const aliasGenerici = new Set([
  'info',
  'hello',
  'contact',
  'contacts',
  'sales',
  'office',
  'admin',
  'support',
  'business',
  'marketing',
  'event',
  'events',
  'partnership',
  'partnerships',
  'enquiry',
  'enquiries',
  'inquiry',
  'inquiries',
  'recruitment',
  'careers',
  'career',
  'hr',
  'hq',
  'general',
  'enquire',
  'booking',
  'bookings',
  // malese / indonesiano
  'pertanyaan',
  'informasi',
  'kontak',
  'hubungi',
  'cs'
]);

const generiche = [];
const personali = [];

for (const email of emailDominio) {

  const local =
    email.split('@')[0];

  if (aliasGenerici.has(local)) {
    generiche.push(email);
