  if (!link) {
    return '';
  }


  // Link inutili
  if (
    link.startsWith('#') ||
    /^mailto:/i.test(link) ||
    /^tel:/i.test(link) ||
    /^javascript:/i.test(link) ||
    /^data:/i.test(link)
  ) {
    return '';
  }


  // URL completo
  if (/^https?:\/\//i.test(link)) {
    return link;
  }


  // URL //azienda.com/contact
  if (/^\/\//.test(link)) {
    return 'https:' + link;
  }


  if (!origin) {
    return '';
  }


  // /contact
  if (link.startsWith('/')) {
    return origin + link;
  }


  // ./contact
  link =
    link.replace(/^\.\//, '');


  // contact
  return origin + '/' + link;
};


