}

let lotto = '';
let paese = '';
try {
  const g = $('Genera 5 Lotti').all()[$itemIndex]?.json ?? $('Genera 5 Lotti').item.json;
  lotto = g.lotto;
  paese = g.paese || '';
} catch {}

// Ogni candidato porta con se il paese del lotto.
candidati = candidati.map(c => ({ ...c, paese: c?.paese || paese }));

return {
  json: {
    output: JSON.stringify({ candidati }),
    lotto,
    stato_lotto: stato,
    candidati_lotto: candidati.length,
    errore
  }
};

// Una riga di statistiche per esecuzione (scheda Log).
// Parte dopo tutti i salvataggi.
const n = (nome, ramo) => {
  try {
    return $(nome).all(ramo ?? 0).length;
  } catch {
    return 0;
  }
};

const conta = (nome, ramo, f) => {
  try {
    return $(nome).all(ramo ?? 0).filter(f).length;
  } catch {
    return 0;
  }
};

const tutti = $('Aggiungi da riprovare').all().map(i => i.json);
const lotti = tutti.filter(l => l.stato_lotto !== 'RIPROVA');
const riprovati = tutti.reduce((s, l) => s + (l.riprovati || 0), 0);

const candidatiAI = lotti.reduce((s, l) => s + (l.candidati_lotto || 0), 0);

// La deduplica emette un item vuoto quando non ci sono nuovi prospect.
let nuovi = 0;
try {
  nuovi = $('Deduplica e prepara righe').all().filter(i => i.json.Nome).length;
} catch {}

const nuoviAI = Math.max(nuovi - riprovati, 0);

const stato = (s) => conta('Prepara righe finali', 0, i => i.json['Stato RocketReach'] === s);
const daRiprovare = conta('Prepara scartati', 0, i =>
  String(i.json['Motivo scarto'] ?? '').startsWith('Da riprovare')
);
const escluse = conta('Prepara righe finali', 0, i =>
  String(i.json['Stato RocketReach'] ?? '').startsWith('ESCLUSA')
);

return [{
  json: {
    'Data ora': $now.setZone('Asia/Singapore').toFormat('yyyy-MM-dd HH:mm'),
    'Execution ID': $execution.id,
    'Lotti': lotti.length,
    'Lotti falliti': lotti.filter(l =>
      l.stato_lotto === 'ERRORE' || l.stato_lotto === 'JSON NON VALIDO'
    ).length,
    'Lotti recuperati': lotti.filter(l => l.stato_lotto === 'RECUPERATO').length,
    'Candidati AI': candidatiAI,
    'Scartati deduplica': Math.max(candidatiAI - nuoviAI, 0),
    'Nuovi candidati': nuoviAI,
    '% nuovi': candidatiAI ? Math.round(nuoviAI / candidatiAI * 100) : 0,
    'Email da sito': n('Email certa trovata?', 0),
    'Lookup RocketReach': n('RocketReach - Lookup persona'),
    'RocketReach non trovati': stato('PERSONA NON TROVATA'),
    'Email da RocketReach': n('Email RocketReach trovata?', 0),
    'Salvati Prospect AI': n('Ha email?', 0),
    'Scartati senza email': n('Ha email?', 1) - daRiprovare - escluse,
    'Righe Mailup': n('Prepara Mailup'),
    'Riprovati da Scartati': riprovati,
    'Ricontrolli RocketReach': n('RocketReach - Status check 2'),
    'RocketReach rate limit': stato('RATE LIMIT'),
    'Da riprovare': daRiprovare,
    'Rinviati tetto RocketReach': stato('RINVIATO (TETTO)'),
    'Escluse grandi aziende': escluse
  }
}];

// Reinserisce (max 40) i prospect scartati 'Da riprovare'
// (limite RocketReach): ripassano dalla ricerca email
// senza pagare una nuova ricerca AI. Hanno la precedenza
// nel tetto RocketReach.
const items = $input.all();
const archivio = $('Prepara archivio').first().json;
const bloccati = new Set(archivio.nomi_esistenti || []);

const norm = (v) => String(v ?? '')
  .normalize('NFKD')
  .replace(/[̀-ͯ]/g, '')
  .toLowerCase()
  .replace(/&/g, ' and ')
  .replace(/[^a-z0-9]+/g, ' ')
  .replace(/\s+/g, ' ')
  .trim();

const MAX = 40;
const visti = new Set();
const candidati = [];

for (const r of $('Read Scartati').all()) {
  const j = r.json;
  if (!String(j['Motivo scarto'] ?? '').startsWith('Da riprovare')) continue;

  const n = norm(j.Nome);
  const sito = String(j.Sito ?? '').trim();
  if (!n || !sito || bloccati.has(n) || visti.has(n)) continue;

  visti.add(n);
  const parti = String(j.Nome).trim().split(/\s+/);

  candidati.push({
    nome: j.Nome,
    nome_proprio: j['Nome Mailup'] || parti[0],
    cognome: j['Cognome Mailup'] || parti.slice(1).join(' '),
    azienda: j.Azienda,
    paese: j.Paese || '',
    ruolo: j.Ruolo,
    settore: j.Settore,
    sito,
    fonte: /^https?:\/\//i.test(sito) ? sito : 'https://' + sito
  });

  if (candidati.length >= MAX) break;
}

if (candidati.length) {
  items.push({
    json: {
      output: JSON.stringify({ candidati }),
      lotto: 'riprova',
      stato_lotto: 'RIPROVA',
      candidati_lotto: 0,
      riprovati: candidati.length
    }
  });
}

return items;

// Aggiorna la scheda Temi: ultimo uso, numero di usi,
// candidati restituiti e quanti erano nuovi (non in archivio).
const norm = (v) => String(v ?? '')
  .normalize('NFKD')
  .replace(/[̀-ͯ]/g, '')
  .toLowerCase()
  .replace(/&/g, ' and ')
  .replace(/[^a-z0-9]+/g, ' ')
  .replace(/\s+/g, ' ')
  .trim();

const temi = Object.fromEntries(
  $('Read Temi').all().map(i => [String(i.json.ID), i.json])
);
const genera = $('Genera 5 Lotti').all().map(i => i.json);
const lotti = Object.fromEntries(genera.map(g => [String(g.lotto), g]));
const archivio = $('Prepara archivio').first().json;
const nomiEsistenti = new Set(archivio.nomi_esistenti || []);

const ora = $now.setZone('Asia/Singapore').toFormat('yyyy-MM-dd HH:mm');
const out = [];

$input.all().forEach((it, idx) => {
  const j = it.json;
  // Un lotto AI per ogni lotto generato, nello stesso ordine.
  const g = lotti[String(j.lotto)] || genera[idx];
  if (!g || !g.tema_id) return;

  const t = temi[String(g.tema_id)] || {};

  let candidati = [];
  try {
    candidati = JSON.parse(j.output).candidati || [];
  } catch {}

  const nuovi = candidati.filter(c => {
    const n = norm(c?.nome);
    return n && !nomiEsistenti.has(n);
  }).length;

  out.push({
    json: {
      ID: g.tema_id,
      'Ultimo uso': ora,
      'Usi': String((Number(t.Usi) || 0) + 1),
      'Candidati totali': String((Number(t['Candidati totali']) || 0) + candidati.length),
      'Nuovi totali': String((Number(t['Nuovi totali']) || 0) + nuovi),
      'Ultimo esito': `${j.stato_lotto}: ${nuovi}/${candidati.length} nuovi`
    }
  });
});

return out;

// Tetto alle ricerche RocketReach per esecuzione: RocketReach ha un
// limite orario (~70 ricerche). Precedenza ai prospect ripresi da
// 'Da riprovare'; chi resta fuori va negli Scartati come 'Da riprovare'.
const TETTO = 60;

const norm = (v) => String(v ?? '').trim().toLowerCase();

const ripresi = new Set();
try {
  for (const it of $('Aggiungi da riprovare').all()) {
    if (it.json.stato_lotto !== 'RIPROVA') continue;
    const candidati = JSON.parse(it.json.output || '{}').candidati || [];
    for (const c of candidati) ripresi.add(norm(c?.nome));
  }
} catch {}

const ordinati = $input.all()
  .map((it, i) => ({ it, i, prio: ripresi.has(norm(it.json.Nome)) ? 0 : 1 }))
  .sort((a, b) => a.prio - b.prio || a.i - b.i);

return ordinati.map((x, pos) => ({
  json: { ...x.it.json, entro_tetto_rr: pos < TETTO },
  pairedItem: { item: x.i }
}));

// Oltre il tetto: niente ricerca RocketReach in questa esecuzione.
// Finisce negli Scartati come 'Da riprovare' e viene ripreso dopo.
return {
  json: {
    ...$json,
    'Email RocketReach': '',
    'Email RocketReach tutte': '',
    'LinkedIn RocketReach': '',
    'Stato RocketReach': 'RINVIATO (TETTO)'
  }
};

// Esclude SOLO le grandi aziende palesi (nessuna stima dell'AI):
// 1) marchio nella scheda Esclusioni, riconosciuto dal dominio del sito
//    (es. deloitte.com) o dal nome, se il marchio e di 2+ parole o il nome
//    coincide esattamente (cosi "Apple Dental Clinic" NON viene escluso);
// 2) forma societaria da quotata/pubblica: Tbk, Berhad/Bhd senza Sdn, plc.
const norm = (v) => String(v ?? '')
  .normalize('NFKD')
  .replace(/[̀-ͯ]/g, '')
  .toLowerCase()
  .replace(/&/g, ' and ')
  .replace(/[^a-z0-9]+/g, ' ')
  .replace(/\s+/g, ' ')
  .trim();

const azienda = norm($json.Azienda);
const host = String($json.Sito ?? '')
  .toLowerCase()
  .replace(/^https?:\/\//, '')
  .split('/')[0]
  .replace(/^www\./, '');
const etichette = host.split('.');

let motivo = '';

for (const r of $('Read Esclusioni').all()) {
  const j = r.json;
  if (String(j.Attivo ?? 'SI').trim().toUpperCase() === 'NO') continue;

  const p = norm(j['Nome o marchio']);
  if (!p) continue;

  const compatti = [p.replace(/ /g, ''), p.replace(/ and /g, ' ').replace(/ /g, '')];
  const perDominio = compatti.some(c => etichette.includes(c));
  const perNome =
    azienda === p ||
    (p.includes(' ') && ` ${azienda} `.includes(` ${p} `));

  if (perDominio || perNome) {
    motivo = `in lista Esclusioni (${j['Nome o marchio']})`;
    break;
  }
}

if (!motivo) {
  if (/\btbk\b/.test(azienda)) {
    motivo = 'quotata in Indonesia (Tbk)';
  } else if (/\b(berhad|bhd)\b/.test(azienda) && !/\bsdn\b/.test(azienda)) {
    motivo = 'societa pubblica in Malesia (Berhad)';
  } else if (/\bplc\b/.test(azienda)) {
    motivo = 'societa quotata (plc)';
  }
}

return {
  json: {
    ...$json,
    esclusa: Boolean(motivo),
    motivo_esclusione: motivo
  }
};

// Grande azienda palese: niente ricerca email ne RocketReach.
// Finisce negli Scartati con motivo definitivo.
return {
  json: {
    ...$json,
    'Email trovata sito': '',
    'Email RocketReach': '',
    'LinkedIn RocketReach': '',
    'Stato RocketReach': 'ESCLUSA: ' + $json.motivo_esclusione
  }
};
